async function api(path,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000),key=body&&['orders/create','orders/action'].includes(path)?crypto.randomUUID():null;try{if(!navigator.onLine){if(body)return await offlineQueue(path,body,key);const cached=await offlineSnapshot(path);cached.offline=true;return cached}const headers=body?{'Content-Type':'application/json'}:{};if(key)headers['X-Idempotency-Key']=key;const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers,body:body?JSON.stringify(body):undefined,cache:'no-store',signal:controller.signal});const data=await r.json();if(!r.ok){const e=new Error(data.error||'İşlem tamamlanamadı.');e.status=r.status;throw e}await putSnapshot(path,data);if(path==='state'){data=await overlayLocalOrders(data);if(data.pendingWrites) data.syncPending=true}return data}catch(e){if(body&&(navigator.onLine===false||e instanceof TypeError||e.name==='AbortError'))return await offlineQueue(path,body,key);if(!body&&(navigator.onLine===false||e instanceof TypeError||e.name==='AbortError'))return await offlineSnapshot(path);if(e.name==='AbortError')throw new Error('Sunucu yanıt vermedi. Bağlantını kontrol edip tekrar dene.');throw e}finally{clearTimeout(timer)}}
