function stat(label,value,hint){return `<div class="stat"><label>${label}</label><strong>${value}</strong><small>${hint}</small></div>`}const sum=a=>a.reduce((s,o)=>s+safeMoneyValue(o),0);function eligible(){return orders.filter(o=>o.serviceType==='package'&&(brandFilter==='all'||o.brand===brandFilter)&&(platformFilter==='all'||o.platform===platformFilter)&&(!query||[o.id,o.customer,...o.items].join(' ').toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr'))))}function age(o){return Math.max(0,Math.floor(((o.delivered||Date.now())-o.created)/60000))}
function productNoteForOrder(o,index){return o.productNotes?.find(n=>n.index===index)?.note||o.adjustments?.find(a=>a.index===index&&a.status==='product_note')?.note||''}function orderLineMarkup(o,item,index){const note=productNoteForOrder(o,index);return esc(item)+(note?'<div class="order-line-note">↳ Not: '+esc(note)+'</div>':'')}function openProductNoteDialog(id,mode='add',index=null){const product=products.find(p=>p.id===id),order=activeTableOrder(),note=mode==='saved'?productNoteForOrder(order||{},index):orderCartNotes.get(id)||'';productNoteTarget={id,mode,index};document.getElementById('productNoteTitle').textContent=mode==='add'?'Ürünü sepete ekle':mode==='saved'?'Ürün notunu düzenle':'Ürün notunu düzenle';document.getElementById('productNoteProduct').textContent=mode==='saved'?parseLine(order?.items[index]||'')?.name||'Ürün':product?.name||'Ürün';document.getElementById('productNoteInput').value=note;document.getElementById('productNoteDialog').showModal()}async function saveProductNoteDialog(){if(!productNoteTarget)return;const target=productNoteTarget,note=document.getElementById('productNoteInput').value.trim().slice(0,320),dialog=document.getElementById('productNoteDialog');if(target.mode==='saved'){const order=activeTableOrder();if(!order){toast('Açık masa adisyonu bulunamadı.',true);return}if(!await mutate('orders/action',{id:order.id,version:order.version,action:'product_note_set',index:target.index,note}))return;renderSavedTableItems();toast(note?'Ürün notu kaydedildi.':'Ürün notu kaldırıldı.')}else if(target.mode==='add'){orderCart.set(target.id,Math.min(50,(orderCart.get(target.id)||0)+1));orderNotedProducts.add(target.id);if(note)orderCartNotes.set(target.id,note);else orderCartNotes.delete(target.id);renderOrderCart()}else{orderNotedProducts.add(target.id);if(note)orderCartNotes.set(target.id,note);else orderCartNotes.delete(target.id);renderOrderCart()}dialog.close();productNoteTarget=null}function receiptDateParts(timestamp){const date=new Date(timestamp||Date.now()),dateText=new Intl.DateTimeFormat('tr-TR',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'Europe/Istanbul'}).format(date),timeText=new Intl.DateTimeFormat('tr-TR',{hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:'Europe/Istanbul'}).format(date);return {dateText,timeText}}
