function printBrandLogos(order){let brands=Array.isArray(order._brands)?order._brands:[];if(!brands.length){if(order.brand==='mixed')brands=['wingy','mac'];else brands=[order.brand==='mac'?'mac':'wingy']}const names=brands.map(value=>value==='mac'?'EASY MACARONI':'EASY WINGY');return '<div class="receipt-business-name" style="text-align:center;font-weight:800;font-size:16px;line-height:1.2;margin:0 auto 6px;">'+names.map(esc).join(' · ')+'</div>'}
function receiptInfoRows(order){const {dateText,timeText}=receiptDateParts(order.created),type=order.serviceType==='table'?'Masa '+(order.tableNo||''):order.serviceType==='pickup'?'Gel-Al':'Paket Servis',staff=order.waiterName||order.staffName||me?.name||'—';return '<div class="receipt-info"><div><b>Tarih :</b><span>'+dateText+'</span></div><div><b>Saat :</b><span>'+timeText+'</span></div>'+(printOptions().orderNo?'<div><b>Ad. No :</b><span>#'+esc(order.id)+'</span></div>':'')+'<div><b>Masa / Tür :</b><span>'+esc(type)+'</span></div><div><b>Garson :</b><span>'+esc(staff)+'</span></div></div>'}
function receiptItemsTable(order,kitchen=false){let source=(order.items||[]).map((item,index)=>{const line=parseLine(item),note=printOptions().notes?productNoteForOrder(order,index):'';return {line,name:line?.name||item,quantity:line?.quantity||1,unit:line?.unit||0,note,index}});if(printOptions().merge){const groups=new Map();for(const row of source){const key=row.name+'|'+row.unit,old=groups.get(key);if(old){old.quantity+=row.quantity;old.notes=[...new Set([...old.notes,...(row.note?[row.note]:[])])]}else groups.set(key,{...row,notes:row.note?[row.note]:[]})}source=[...groups.values()]}const rows=source.map(row=>{const amount=row.quantity*row.unit/100;return '<tr><td class="qty-col">'+row.quantity+'</td><td class="name-col"><strong>'+esc(row.name)+'</strong>'+(row.notes?.length?'<small class="receipt-kitchen-note">'+esc(row.notes.join(' · '))+'</small>':'')+'</td>'+(kitchen?'':'<td class="amount-col">'+receiptMoney(amount)+'</td>')+'</tr>'}).join('');return '<table class="receipt-table" style="width:100%;border-collapse:collapse;table-layout:fixed;"><colgroup><col style="width:15%"><col style="width:55%"><col style="width:30%"></colgroup><thead><tr><th class="qty-col">Adet</th><th class="name-col">Cinsi</th>'+(kitchen?'':'<th class="amount-col">Tutar</th>')+'</tr></thead><tbody>'+rows+'</tbody></table>'}
function printNow(){const ticket=document.getElementById('printTicket'),opts=printOptions();ticket.style.fontSize=Number(opts.fontSize||12)+'px';ticket.classList.toggle('print-compact',!!opts.compact);ticket.hidden=false;requestAnimationFrame(()=>{window.addEventListener('afterprint',()=>{ticket.hidden=true},{once:true});window.print()})}
function printKitchenTicket(order){const ticket=document.getElementById('printTicket'),label=order.serviceType==='table'?'Masa '+order.tableNo:order.serviceType==='pickup'?'Gel-Al':'Paket Servis';ticket.innerHTML='<div class="ticket kitchen-ticket" style="width:72mm; margin:0 auto; font-family:monospace; font-size:12px; color:#000;">'+printBrandLogos(order)+receiptInfoRows(order)+'<div class="receipt-ticket-type">MUTFAK · '+esc(label)+'</div>'+receiptItemsTable(order,true)+(order.note?'<div class="receipt-order-note"><b>SİPARİŞ NOTU</b><br>'+esc(order.note)+'</div>':'')+'</div>';printNow()}
function printAccountSlip(order){toast('Hesap fişi yerel yazdırma kuyruğuna gönderildi.')}
function printCashierCourierSlip(order){api('printers/manage',{action:'queue_order',id:order.id,type:'Adisyon'}).then(()=>toast('Kasa fişi yerel yazdırma kuyruğuna eklendi.')).catch(error=>toast(error.message,true));return;const ticket=document.getElementById('printTicket'),discount=Number(order.discountAmount||0),discountLabel=order.discountType==='percent'?'Adisyon indirimi (%'+(Number(order.discountValue||0)).toLocaleString('tr-TR')+')':'Uygulanan indirim',vat=printOptions().vat?'<div><span>KDV (dahil %10)</span><b>'+receiptMoney(Number(order.total||0)*10/110)+'</b></div>':'';ticket.innerHTML='<div class="ticket cashier-ticket" style="width:72mm; margin:0 auto; font-family:monospace; color:#000;">'+printBrandLogos(order)+receiptInfoRows(order)+'<div class="receipt-customer-info"><div><b>Müşteri :</b><span>'+esc(order.customer||'—')+'</span></div><div><b>Ödeme :</b><span>'+esc(order.payment||'—')+'</span></div><div><b>Kanal :</b><span>'+esc(order.platform||'Restoran')+'</span></div>'+(order.serviceType==='package'?'<div><b>Adres :</b><span>'+esc(order.area||'—')+'</span></div>':'')+(order.note?'<div class="receipt-order-note"><b>SİPARİŞ NOTU</b><br>'+esc(order.note)+'</div>':'')+'</div>'+receiptItemsTable(order,false)+'<div class="receipt-totals"><div><span>Ara Toplam</span><b>'+receiptMoney(order.subtotal)+'</b></div>'+(discount>0?'<div><span>'+esc(discountLabel)+'</span><b>−'+receiptMoney(discount)+'</b></div>':'')+vat+'<div class="receipt-grand-total"><span>Toplam</span><b>'+receiptMoney(order.total)+'</b></div></div>'+(order.serviceType==='package'?'<div class="receipt-courier-info"><b>Müşteri :</b> '+esc(order.customer||'—')+'<br><b>Telefon :</b> '+esc(order.phone||'—')+'<br><b>Açık Adres :</b><br><strong>'+esc(order.area||'—')+'</strong></div>':'')+'</div>';printNow()}
function card(o,mode='admin'){const mine=o.courierId===activeCourier;let action='';if(mode==='admin'){if(o.stage===0||o.stage===1)action=`<button data-action="ready" data-id="${o.id}" class="primary">Hazırlandı →</button>`;else if(o.stage===2&&o.serviceType!=='package')action=`<button data-action="deliver" data-id="${o.id}" class="primary">${o.serviceType==='pickup'?'Gel Al teslim edildi ✓':'Masayı kapat ✓'}</button>`;else if(o.stage===2)action=o.courierId?`<button data-action="depart" data-id="${o.id}" class="primary">Yola çıkar →</button><button style="margin-top:6px" data-action="release" data-id="${o.id}">Havuza bırak</button>`:`<button data-action="assign" data-id="${o.id}" ${couriers().length?'':'disabled'}>Kurye ata →</button>`;else if(o.stage===3)action=`<button data-action="deliver" data-id="${o.id}" class="primary">Teslim edildi ✓</button>`}else{if(o.serviceType==='package'&&o.stage===2&&!o.courierId)action=`<button data-action="claim" data-id="${o.id}" class="primary" ${activeCourier?'':'disabled'}>Üzerime al</button>`;else if(o.stage===2&&mine)action=`<button data-action="depart" data-id="${o.id}" class="primary">Yola çıktım →</button><button style="margin-top:6px" data-action="release" data-id="${o.id}">Havuza bırak</button>`;else if(o.stage===3&&mine)action=`<button data-action="deliver" data-id="${o.id}" class="primary">${o.payment==='Online'?'Teslim ettim ✓':'Tahsil ettim ve teslim ettim ✓'}</button>`}return `<article class="card order-card-open" data-order-open="${o.id}"><div class="card-top"><span class="platform ${o.platform==='Trendyol'?'trendyol':''}">${esc(o.platform)}</span><b>#${o.id}</b></div><span class="brand ${o.brand==='mac'?'mac':''}">${brand(o.brand)}</span><div class="fine">${o.serviceType==='package'?'Paket':o.serviceType==='pickup'?'Gel Al':`Masa ${o.tableNo||''}`}</div><div class="customer">${esc(o.customer)}</div><div class="area">${esc(o.area)} · <span class="age" data-age-id="${o.id}">${age(o)} dk${o.stage===4?' · tamamlandı':''}</span></div><div class="items">${o.items.map((item,index)=>orderLineMarkup(o,item,index)).join('<br>')}</div>${o.note?`<div class="note">Not: ${esc(o.note)}</div>`:''}<div class="payment"><span>${['Online','Online Ödeme','YS Online','Trendyol Online'].includes(o.payment)?'✓ Online ödendi':o.payment==='Açık Hesap'?'Açık hesap':o.stage===4?o.payment+' tahsil edildi':o.payment==='Nakit'?'₺ Nakit tahsil et':'▣ Kart tahsil et'}</span><strong>${money(o.total)}</strong></div>${o.courierId?`<div class="courier-name">↗ ${esc(person(o.courierId))}${o.stage===2?' · paket ayrıldı':''}</div>`:''}${action}</article>`}
function board(a){const columns=[{label:stages[1],icon:'◷',match:o=>o.stage===0||o.stage===1},{label:stages[2],icon:'◇',match:o=>o.stage===2},{label:stages[3],icon:'↗',match:o=>o.stage===3},{label:stages[4],icon:'✓',match:o=>o.stage===4}];return columns.map(c=>{const rows=a.filter(c.match);return `<section class="column"><div class="column-title"><span>${c.icon} &nbsp;${c.label}</span><span class="count">${rows.length}</span></div>${rows.map(o=>card(o)).join('')||'<div class="empty">Bu aşamada sipariş yok</div>'}</section>`}).join('')}

function renderPickup(){const a=orders.filter(o=>o.serviceType==='pickup');const columns=[{label:'Hazırlanıyor',match:o=>o.stage===0||o.stage===1},{label:'Teslime hazır',match:o=>o.stage===2},{label:'Teslim edildi',match:o=>o.stage===4}];document.getElementById('app').innerHTML=`<div class="heading"><div><h2>Gel Al siparişleri.</h2><div class="sub">Müşteri restorandan teslim alacak siparişler.</div></div><button class="primary" data-action="newOrder" data-service="pickup">+ Yeni Gel Al siparişi</button></div><div class="stats">${stat('Açık sipariş',a.filter(o=>o.stage<4).length,'Hazırlanan ve hazır')}${stat('Teslim edildi',a.filter(o=>o.stage===4).length,'Bugün')}${stat('Hazır bekleyen',a.filter(o=>o.stage===2).length,'Müşteri teslim alabilir')}${stat('Toplam satış',money(sum(a.filter(o=>o.stage===4))),'Tamamlanan')}</div><div class="board service-board">${columns.map(c=>{const rows=a.filter(c.match);return `<section class="column"><div class="column-title"><span>${c.label}</span><span class="count">${rows.length}</span></div>${rows.map(o=>card(o)).join('')||'<div class="empty">Sipariş yok</div>'}</section>`}).join('')}</div>`}
function renderTables(){const active=orders.filter(o=>o.serviceType==='table'&&o.stage<4&&!o.mergedInto),byTable=new Map(active.map(o=>[o.tableNo,o]));document.getElementById('app').innerHTML=`<div class="heading"><div><h2>Salon · 9 masa</h2><div class="sub">Masaya dokunup ürün ekleyebilir, hesap ve masa işlemlerini yönetebilirsin.</div></div></div><div class="floor-plan">${Array.from({length:9},(_,i)=>{const n=i+1,o=byTable.get(n),activeItems=o?o.items.filter((item,index)=>!o.adjustments?.some(a=>a.index===index&&['cancelled','refunded','comp','paid'].includes(a.status))):[];return `<button type="button" class="table-card ${o?'occupied':''} ${o?.billRequested?'bill-requested':''}" data-table-open="${n}"><span class="table-number">Masa ${n}</span><strong>${o?(o.billRequested?'HESAP İSTENDİ':'DOLU'):'BOŞ'}</strong>${o?`<small>${brand(o.brand)} · #${o.id}</small><b>${money(o.total)}</b><small class="table-items-preview">${activeItems.slice(0,2).map(item=>esc(parseLine(item)?.name||item)).join(' · ')||'Aktif ürün yok'}${activeItems.length>2?' · +'+(activeItems.length-2)+' ürün':''}</small><small>${activeItems.length} kalem · <span data-table-age data-opened="${o.created}">${age(o)} dk açık</span></small>`:'<small>Yeni sipariş aç</small>'}</button>`}).join('')}</div>`;document.querySelectorAll('[data-table-open]').forEach(button=>button.addEventListener('click',()=>openOrder('table',button.dataset.tableOpen)))}
