let orderMenuKey='',orderMenuCategories='',orderMenuProducts=new Map();function renderOrderMenu(){const activeProducts=products.filter(p=>p.active!==false),key=activeProducts.map(p=>`${p.id}:${p.name}:${p.category}:${p.ysPrice}`).join('|');if(key!==orderMenuKey){orderMenuKey=key;const cats=[...new Set(activeProducts.map(p=>p.category))];orderMenuCategories=cats.map(c=>[c,`<button type="button" data-order-category="${esc(c)}">${esc(c)}</button>`]);orderMenuProducts.clear();if(!cats.includes(orderCategory))orderCategory=cats[0]||'all'}document.getElementById('orderCategories').innerHTML=orderMenuCategories.map(([c,html])=>html.replace('<button ','<button class="'+(orderCategory===c?'selected':'')+'" ')).join('');if(!activeProducts.some(p=>p.category===orderCategory))orderCategory=activeProducts[0]?.category||'all';let markup=orderMenuProducts.get(orderCategory);if(!markup){markup=activeProducts.filter(p=>p.category===orderCategory).map(p=>`<button type="button" class="order-product" data-add-product="${p.id}"><strong>${esc(p.name)}</strong><small>${esc(p.category)} · ${p.brand==='mac'?'Easy Macaroni':p.brand==='shared'?'Ortak ürün':'Easy Wingy'}</small><b>${money(p.ysPrice/100)}</b></button>`).join('');orderMenuProducts.set(orderCategory,markup)}document.getElementById('orderProducts').innerHTML=markup}
function discountAmountFor(subtotal){return discountType==='percent'?Math.min(subtotal,Math.round(subtotal*discountValue/10000)):discountType==='amount'?Math.min(subtotal,discountValue):0}
function renderOrderSummary(){const existing=orderService==='table'?activeTableOrder():null,kind=orderService==='table'?'Masa servisi':orderService==='pickup'?'Gel Al':'Paket sipariş';document.getElementById('posOrderKind').textContent=kind;document.getElementById('posOrderTable').textContent=orderService==='table'?'Masa '+orderTableNo:orderService==='pickup'?'Gel Al':'Paket';document.getElementById('posOrderStaff').textContent=me?.name||'Personel';document.getElementById('posOrderNumber').textContent=existing?'#'+existing.id:'Yeni';document.getElementById('posOrderNumber').classList.toggle('is-new',!existing)}
function productBrandByName(name){return products.find(p=>p.name===name)?.brand||''}function brandIcon(brand){const file=brand==='mac'?'/brand/macaroni-icon.png':brand==='wingy'?'/brand/wingy-icon.png':'';return file?'<img class=\"brand-mark\" src=\"'+file+'\" alt=\"'+(brand==='mac'?'Easy Macaroni':'Easy Wingy')+'\" title=\"'+(brand==='mac'?'Easy Macaroni':'Easy Wingy')+'\">':''}
function renderOrderCart(){const isTable=orderService==='table',heading=document.getElementById('cartHeading'),cart=document.getElementById('orderCart');if(heading)heading.hidden=isTable;if(cart)cart.hidden=isTable;const rows=[...orderCart.entries()].map(([id,q])=>{const p=products.find(x=>x.id===id);if(!p)return'';const note=orderCartNotes.get(id)||'';return `<div class="cart-row"><button type="button" class="cart-item-identity" data-cart-note="${id}" aria-label="${esc(p.name)} ürün notunu düzenle">${brandIcon(p.brand)}<span><b>${esc(p.name)}</b><small>${money(p.ysPrice/100)} / adet</small><em class="cart-line-note">${note?'Not: '+esc(note):'Ürün notu ekle'}</em></span></button><div><button type="button" data-cart-minus="${id}" aria-label="${esc(p.name)} adedini azalt">−</button><b>${q}</b><button type="button" data-cart-plus="${id}" aria-label="${esc(p.name)} adedini artır">+</button><button type="button" data-cart-remove="${id}" aria-label="Ürünü sil">×</button></div><strong>${money(p.ysPrice*q/100)}</strong></div>`}).join('');if(cart)cart.innerHTML=rows||'<div class="empty">Henüz ürün eklenmedi.</div>';const cartSubtotal=[...orderCart.entries()].reduce((sum,[id,q])=>sum+(products.find(p=>p.id===id)?.ysPrice||0)*q,0),existing=isTable?activeTableOrder():null,subtotal=cartSubtotal+Math.round((existing?.subtotal||0)*100),discount=discountAmountFor(subtotal),total=Math.max(0,subtotal-discount);document.getElementById('orderTotal').textContent=money(total/100);document.getElementById('orderDiscountSummary').textContent=discount?'İndirim: −'+money(discount/100):'İndirim uygulanmadı';document.getElementById('saveOrder').disabled=!orderCart.size;document.getElementById('posPay').disabled=isTable?(!existing&&!orderCart.size):!orderCart.size;const billPrint=document.getElementById('posBillPrint');if(billPrint){billPrint.hidden=!isTable;billPrint.disabled=!isTable||(!existing&&!orderCart.size)}const transfer=document.getElementById('posTableTransfer');if(transfer)transfer.disabled=!isTable||(!existing&&!orderCart.size);renderOrderSummary();if(isTable)renderSavedTableItems()}
function activeTableOrder(){return orders.find(o=>o.serviceType==='table'&&o.tableNo===orderTableNo&&o.stage<4)}
function parseLine(value){const m=String(value).match(/^(\d+) × (.+) · ₺([\d.,]+)$/);if(!m)return null;return {quantity:Number(m[1]),name:m[2],unit:Math.round(Number(m[3].replace(/\./g,'').replace(',','.'))*100)}}
function adjustmentStatus(order,index){return order.adjustments?.find(a=>a.index===index&&['cancelled','refunded','comp','paid'].includes(a.status))?.status||''}
function renderSavedTableItems(){const wrap=document.getElementById('savedTableItems');if(!wrap)return;const o=activeTableOrder();wrap.hidden=orderService!=='table';if(orderService!=='table')return;const savedLines=o?(o.items||[]).map((item,index)=>{const line=parseLine(item),status=adjustmentStatus(o,index),note=productNoteForOrder(o,index),label=status==='cancelled'?'İptal edildi':status==='refunded'?'İade · Zayi':status==='comp'?'İkram':status==='paid'?'Ödendi':'',adjustment=o.adjustments?.find(a=>a.index===index&&['cancelled','refunded','comp','paid'].includes(a.status)),itemDiscount=(o.adjustments||[]).filter(a=>a.index===index&&a.status==='item_discount').reduce((n,a)=>n+Number(a.amount||0),0),partialPaid=(o.adjustments||[]).filter(a=>a.index===index&&a.status==='partial_paid').reduce((n,a)=>n+Number(a.amount||0),0),shownPrice=status==='comp'?0:line?Math.max(0,line.quantity*line.unit-itemDiscount-partialPaid)/100:0;return `<div class="saved-line ${status?'adjusted':''}"><div class="saved-line-main"><button type="button" class="saved-product-identity" data-saved-product-note="${index}" title="Ürün notunu düzenle">${line?brandIcon(productBrandByName(line.name)):''}<strong>${line?esc(line.name):esc(item)}</strong></button>${note?`<small class="saved-product-note">Not: ${esc(note)}</small>`:''}<small>${line?line.quantity+' × '+money(line.unit/100):''}${label?` · <b class="line-status ${status}">${label}</b>`:''}${['refunded','paid'].includes(status)&&adjustment?.amount?` · ${money(adjustment.amount/100)}`:''}</small><b class="saved-line-price ${status==='comp'?'comp-price':''}">${money(shownPrice)}</b></div>${!status&&line?`<div class="saved-line-tools">${o.stage<4?`<button type="button" title="Adedi azalt" data-line-action="line_quantity" data-index="${index}" data-quantity="${line.quantity-1}" ${line.quantity<=1?'disabled':''}>−</button><b>${line.quantity}</b><button type="button" title="Adedi artır" data-line-action="line_quantity" data-index="${index}" data-quantity="${line.quantity+1}">+</button>`:''}${o.serviceType!=='table'&&o.stage===0?`<button type="button" data-line-action="line_cancel" data-index="${index}">İptal</button>`:''}${o.serviceType==='table'||o.stage>=1?`<button type="button" data-line-action="line_refund" data-index="${index}">İade / Zayi</button>`:''}${o.stage<4?`<button type="button" data-line-action="line_comp" data-index="${index}">İkram</button>`:''}</div>`:''}</div>`}).join(''):'';const newLines=[...orderCart.entries()].map(([id,q])=>{const product=products.find(p=>p.id===id);if(!product)return'';const note=orderCartNotes.get(id)||'';return `<div class="saved-line new-order-line"><div class="saved-line-main"><button type="button" class="saved-product-identity" data-cart-note="${id}" title="Ürün notunu düzenle">${brandIcon(product.brand)}<strong>${esc(product.name)}</strong><span class="new-line-indicator">Yeni</span></button>${note?`<small class="saved-product-note">Not: ${esc(note)}</small>`:''}<small>${q} × ${money(product.ysPrice/100)}</small><b class="saved-line-price">${money(product.ysPrice*q/100)}</b></div><div class="saved-line-tools"><button type="button" title="Adedi azalt" data-cart-minus="${id}">−</button><b>${q}</b><button type="button" title="Adedi artır" data-cart-plus="${id}">+</button><button type="button" title="Ürünü kaldır" data-cart-remove="${id}">×</button></div></div>`}).join('');const heading=`<div class="saved-table-heading"><h3>Masa ${orderTableNo} · Adisyon</h3></div>`;const lines=savedLines+newLines;wrap.innerHTML=heading+`<div class="saved-lines unified-adisyon-list">${lines||'<div class="empty">Henüz ürünü yok. Sağdaki menüden ürün seç.</div>'}</div>`}
function paymentTotals(o){const payments=o.payments||[],standard=payments.filter(p=>p.scope!=='items'),paidCents=Math.round(standard.filter(p=>['paid','refund'].includes(p.status)).reduce((s,p)=>s+p.amount,0)*100),receivableCents=Math.round(standard.filter(p=>['receivable','receivable_adjustment'].includes(p.status)).reduce((s,p)=>s+p.amount,0)*100),totalCents=Math.round(o.total*100),allocated=paidCents+receivableCents;return {paid:paidCents,receivable:receivableCents,remaining:Math.max(0,totalCents-allocated),total:totalCents}}
function activeBillLines(o){return o.items.map((item,index)=>({item,index,line:parseLine(item)})).filter(x=>x.line&&!o.adjustments?.some(a=>a.index===x.index&&['cancelled','refunded','comp','paid'].includes(a.status)))}
function paymentLineGross(o,index,line){const adjustments=o.adjustments||[],itemDiscount=adjustments.filter(a=>a.index===index&&a.status==='item_discount').reduce((n,a)=>n+Number(a.amount||0),0),partialPaid=adjustments.filter(a=>a.index===index&&a.status==='partial_paid').reduce((n,a)=>n+Number(a.amount||0),0);return Math.max(0,line.quantity*line.unit-itemDiscount-partialPaid)}
function paymentLineDue(o,index,line){const gross=paymentLineGross(o,index,line),subtotal=Math.round((o.subtotal||o.total)*100),discount=Math.round((o.discountAmount||0)*100),share=subtotal?Math.round(gross*discount/subtotal):0;return Math.max(0,gross-share)}
function selectedBillAmount(o){return activeBillLines(o).filter(x=>selectedBillItems.has(x.index)).reduce((sum,x)=>{const due=paymentLineDue(o,x.index,x.line),denominator=selectedShares.get(x.index)||0;return sum+(denominator?Math.max(1,Math.round(due/denominator)):due)},0)}
function renderPaymentRemainder(){const o=activeTableOrder(),field=document.getElementById('paymentAmount'),remainingLabel=document.getElementById('currentRemaining'),afterLabel=document.getElementById('remainingAfterInput');if(!o||!field||!remainingLabel||!afterLabel)return;const t=paymentTotals(o),entered=Math.max(0,Math.round(Number(String(field.value).replace(',','.'))*100)||0);remainingLabel.textContent=money(t.remaining/100);afterLabel.textContent=money(Math.max(0,t.remaining-entered)/100)}
function renderTablePayment(){const o=activeTableOrder(),pane=document.getElementById('tablePaymentPane');pane.hidden=false;if(!o){pane.innerHTML='<div class="payment-popup"><header class="payment-popup-head"><div><h3>Masa '+orderTableNo+' · Ödeme</h3><p>Açık adisyon bulunamadı.</p></div><button type="button" data-payment-close aria-label="Ödeme penceresini kapat">×</button></header></div>';return}const t=paymentTotals(o),payments=o.payments||[],lines=activeBillLines(o),selectedAmount=selectedBillAmount(o),subtotal=Math.round((o.subtotal||o.total)*100),discount=Math.round((o.discountAmount||0)*100),methods=[['Nakit','Nakit'],['Kredi Kartı','Kredi Kartı'],['Online Ödeme','YS Online'],['Sodexo/Multinet','Sodexo / Multinet'],['Açık Hesap (Cari)','Açık Hesap']];let lineHtml=lines.map(({index,line})=>{const selected=selectedBillItems.has(index),fraction=selectedShares.get(index),due=paymentLineDue(o,index,line),display=money(due/100),fractionLabel=fraction?'Seçili · 1/'+fraction:'Ürün Bazlı 1/n',discounted=(o.adjustments||[]).some(a=>a.index===index&&a.status==='item_discount');return '<div class="bill-select-row '+(selected?'selected':'')+'"><label class="bill-select-row-main" data-select-bill-line="'+index+'"><input type="checkbox" '+(selected?'checked':'')+'><span><b>'+esc(line.name)+'</b><small>'+line.quantity+' × '+money(line.unit/100)+(discounted?' · indirim uygulandı':'')+'</small></span><strong>'+display+'</strong></label><div class="payment-item-actions"><button type="button" data-share-line="'+index+'">'+fractionLabel+'</button><button type="button" data-line-discount="'+index+'">'+(discounted?'İndirimi düzenle':'Ürün Bazlı İndirim')+'</button></div></div>'}).join('');const methodHtml=methods.map(([value,label],i)=>'<button type="button" aria-pressed="'+(paymentMethod===value)+'" class="payment-method method-'+i+' '+(paymentMethod===value?'selected':'')+'" data-payment-method="'+value+'">'+label+'</button>').join('');const initialCents=selectedBillItems.size?selectedAmount:t.remaining;paymentKeyBuffer=String(initialCents);paymentKeyActive=false;pane.innerHTML='<div class="payment-popup"><header class="payment-popup-head"><div><h3>Masa '+orderTableNo+' · Ödeme ve parçalı tahsilat</h3><p>'+esc(brand(o.brand))+' · Açık adisyon #'+o.id+'</p></div><div class="payment-head-total"><div><span>Adisyon</span><strong>'+money(t.total/100)+'</strong></div><div><span>Kalan</span><strong>'+money(t.remaining/100)+'</strong></div><button type="button" data-payment-close aria-label="Ödeme penceresini kapat">×</button></div></header><div class="payment-columns"><section class="payment-items-panel"><div class="payment-section-title"><h4>Parçalı Öde</h4><button type="button" data-open-discount>Adisyon indirimi</button></div><div class="bill-select-list">'+(lineHtml||'<div class="empty">Tahsil edilecek ürün kalmadı.</div>')+'</div><div class="payment-summary-line"><span>Ürün bazlı seçili tutar</span><strong>'+money(selectedAmount/100)+'</strong></div></section><section class="payment-keypad-panel"><h4>Ödenecek tutar</h4><div class="payment-center-total"><span>Ödeme tutarı</span><strong id="paymentAmountLabel">'+money(initialCents/100)+'</strong></div><input id="paymentAmount" class="payment-amount-input" type="text" inputmode="none" readonly aria-label="Ödenecek tutar" value="'+(initialCents/100).toFixed(2)+'"><div class="payment-numpad">'+['1','2','3','4','5','6','7','8','9','clear','0','back','00'].map(k=>'<button type="button" data-key="'+k+'">'+(k==='clear'?'Temizle':k==='back'?'⌫':k)+'</button>').join('')+'</div></section><section class="payment-method-panel"><h4>Ödeme tipleri</h4><div class="payment-methods">'+methodHtml+'</div><div class="payment-summary-line"><span>Ara toplam</span><strong>'+money(subtotal/100)+'</strong></div><div class="payment-summary-line"><span>Adisyon indirimi</span><strong>−'+money(discount/100)+'</strong></div><div class="payment-history">'+payments.map(p=>'<div><span>'+esc(p.method)+' · '+(p.scope==='items'?'Ürün tahsilatı':p.status==='receivable'?'Açık hesap':'Tahsilat')+'</span><b>'+(p.amount<0?'−':'')+money(Math.abs(p.amount))+'</b></div>').join('')+'</div><div class="payment-actions"><button type="button" data-payment-save>Kaydet</button><button type="button" class="primary" data-payment-settle>Öde ve Kapat</button><button type="button" data-payment-print>Öde ve Yazdır</button></div><div class="payment-popup-footer"><button type="button" data-table-transfer-open>Masa taşı / birleştir</button><button type="button" data-payment-close>Kapat</button></div></section></div></div>'}

function openTableTransferDialog(){const order=activeTableOrder();if(!order)return;const occupied=new Map(orders.filter(x=>x.serviceType==='table'&&x.stage<4&&!x.mergedInto).map(x=>[x.tableNo,x]));const select=document.getElementById('tableMoveTarget');select.innerHTML=Array.from({length:9},(_,i)=>i+1).filter(n=>n!==order.tableNo).map(n=>{const target=occupied.get(n);return `<option value="${n}">Masa ${n} · ${target?`Birleştir (${money(target.total)})`:'Boş masa'}</option>`}).join('');updateTableTransferHint();document.getElementById('tableMoveDialog').showModal()}
function updateTableTransferHint(){const targetNo=Number(document.getElementById('tableMoveTarget').value),target=orders.find(x=>x.serviceType==='table'&&x.tableNo===targetNo&&x.stage<4&&!x.mergedInto),hint=document.getElementById('tableMoveHint');if(hint)hint.textContent=target?`Masa ${targetNo} dolu. İki adisyon ürünleri, indirimleri ve ödeme hareketleri korunarak birleştirilecek.`:`Masa ${targetNo} boş. Adisyon bu masaya taşınacak.`}
function switchOrderPane(next){if(orderService!=='table')return;orderPane=next;const payment=next==='payment';const popup=document.getElementById('tablePaymentPane');popup.hidden=!payment;document.getElementById('orderDialog').classList.remove('payment-view');if(payment)renderTablePayment();else renderSavedTableItems()}async function saveOrderItems(closeAfter=false){if(!orderCart.size){if(closeAfter)closeOrderDialog();return true}const payload={serviceType:orderService,tableNo:orderService==='table'?Number(document.getElementById('orderTableNo').value):null,customer:document.getElementById('orderCustomer').value,phone:document.getElementById('orderPhone').value,area:document.getElementById('orderArea').value,note:document.getElementById('orderNote').value,platform:document.getElementById('orderPlatform').value,payment:document.getElementById('orderPayment').value,discountType,discountValue,items:[...orderCart.entries()].map(([id,quantity])=>({id,quantity,productNote:orderCartNotes.get(id)||''}))};if(!document.getElementById('orderForm').reportValidity())return false;let result;if(editingOrderId){const order=orders.find(item=>item.id===editingOrderId);if(!order){toast('Düzenlenecek sipariş bulunamadı.',true);return false}result=await mutate('orders/action',{id:order.id,version:order.version,action:'order_edit',...payload});if(!result)return false;const additions=[];const oldCounts=new Map();for(const row of editOriginalItems){const line=parseLine(row);if(line)oldCounts.set(line.name,(oldCounts.get(line.name)||0)+line.quantity)}for(const entry of payload.items){const product=products.find(item=>item.id===entry.id);if(!product)continue;const old=Math.max(0,oldCounts.get(product.name)||0),added=Math.max(0,entry.quantity-old);oldCounts.set(product.name,Math.max(0,old-entry.quantity));if(added)additions.push({entry:{...entry,quantity:added},product})}const savedOrder=orders.find(item=>item.id===editingOrderId);if(additions.length&&savedOrder){const ticketOrder={...savedOrder,items:additions.map(({entry,product})=>`${entry.quantity} × ${product.name} · ₺${(product.ysPrice/100).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})}`),adjustments:additions.map(({entry},index)=>entry.productNote?{index,status:'product_note',note:entry.productNote}:null).filter(Boolean),note:payload.note,waiterName:me?.name||'—',_brands:[...new Set(additions.map(row=>row.product.brand).filter(value=>value==='wingy'||value==='mac'))]};}editOriginalItems=savedOrder?.items||[];orderCart.clear();orderCartNotes.clear();orderNotedProducts.clear();renderOrderCart();toast('Adisyon aynı sipariş kaydında güncellendi.');if(closeAfter)closeOrderDialog();return true}result=await mutate('orders/create',payload);if(!result)return false;if(orderService==='table'&&orderCart.size){document.querySelectorAll('#savedTableItems .new-line-indicator').forEach(el=>{el.classList.add('is-persisting');el.setAttribute('aria-label','Kaydedildi')});await new Promise(resolve=>setTimeout(resolve,180))}const savedOrder=orders.find(order=>order.id===Number(result.id));if(savedOrder){const added=payload.items.map(entry=>{const product=products.find(item=>item.id===entry.id);return {entry,product}}).filter(row=>row.product),ticketOrder={...savedOrder,items:added.map(({entry,product})=>`${entry.quantity} × ${product.name} · ₺${(product.ysPrice/100).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})}`),adjustments:added.map(({entry},index)=>entry.productNote?{index,status:'product_note',note:entry.productNote}:null).filter(Boolean),note:payload.note,waiterName:me?.name||'—',_brands:[...new Set(added.map(row=>row.product.brand).filter(value=>value==='wingy'||value==='mac'))]};}orderCart.clear();orderCartNotes.clear();orderNotedProducts.clear();renderOrderCart();renderSavedTableItems();if(closeAfter)closeOrderDialog();toast(orderService==='table'?'Ürünler adisyona kaydedildi; masa açık.':'Sipariş kaydedildi.');if(orderService==='table'&&orderPane==='payment')renderTablePayment();return true}
function closeOrderDialog(){clearOrderEntry();editingOrderId=null;editOriginalItems=[];document.getElementById('orderDialog').close()}async function closeOrderScreen(){if(orderService==='table'&&orderCart.size){const ok=await saveOrderItems(false);if(!ok)return}closeOrderDialog()}
async function switchTablePayment(){if(orderCart.size&&!await saveOrderItems(false))return;selectedBillItems.clear();selectedShares.clear();orderPane='payment';document.getElementById('tablePaymentPane').hidden=false;renderTablePayment()}
async function openOrder(service='package',tableNo=null){try{if(!products.length)products=(await api('menu')).products;if(!products.length)throw new Error('Menü yüklenemedi. Sayfayı yenileyip tekrar dene.');editingOrderId=null;editOriginalItems=[];orderService=service;orderTableNo=tableNo?Number(tableNo):null;orderCategory=products[0]?.category||'all';orderCart=new Map();orderCartNotes=new Map();orderNotedProducts=new Set();selectedBillItems.clear();orderPane='products';paymentMethod='Nakit';const existing=service==='table'?orders.find(o=>o.serviceType==='table'&&o.tableNo===orderTableNo&&o.stage<4):null;discountType=existing?.discountType||'none';discountValue=Math.round((existing?.discountValue||0)*100);const form=document.getElementById('orderForm');form.reset();document.getElementById('orderService').value=service;document.getElementById('orderTableNo').value=String(orderTableNo||1);document.getElementById('orderTableNo').disabled=!!orderTableNo;document.getElementById('orderPayment').value='Nakit';document.getElementById('orderTitle').textContent=service==='table'?'Masa '+orderTableNo+' · Adisyon':service==='pickup'?'Yeni Gel Al siparişi':'Yeni paket siparişi';document.getElementById('orderDialog').classList.remove('payment-view');orderTypeFields();renderOrderMenu();renderOrderCart();renderSavedTableItems();renderOrderSummary();document.getElementById('orderDialog').showModal();saveOrderEntry(service,orderTableNo)}catch(e){toast(e.message||'Sipariş ekranı açılamadı.',true)}}

async function openOrderEdit(id){try{const order=orders.find(item=>item.id===Number(id));if(!order||!['package','pickup'].includes(order.serviceType)||order.stage>=4){toast('Yalnızca açık Paket veya Gel-Al siparişleri düzenlenebilir.',true);return}if(!products.length)products=(await api('menu')).products;editingOrderId=order.id;editOriginalItems=[...order.items];orderService=order.serviceType;orderTableNo=null;orderCategory=products[0]?.category||'all';orderCart=new Map();orderCartNotes=new Map();orderNotedProducts=new Set();for(const [index,row] of order.items.entries()){const line=parseLine(row),product=products.find(item=>item.name===line?.name);if(!line||!product)continue;orderCart.set(product.id,(orderCart.get(product.id)||0)+line.quantity);const note=productNoteForOrder(order,index);if(note)orderCartNotes.set(product.id,note)}discountType=order.discountType||'none';discountValue=Math.round((order.discountValue||0)*100);const form=document.getElementById('orderForm');form.reset();document.getElementById('orderService').value=order.serviceType;document.getElementById('orderTableNo').value='1';document.getElementById('orderTableNo').disabled=true;document.getElementById('orderCustomer').value=order.customer||'';document.getElementById('orderPhone').value=order.phone||'';document.getElementById('orderArea').value=order.area||'';document.getElementById('orderPlatform').value=order.platform||'Restoran';document.getElementById('orderPayment').value=order.payment||'Nakit';document.getElementById('orderNote').value=order.note||'';document.getElementById('orderTitle').textContent='Adisyon #'+order.id+' · '+(order.serviceType==='pickup'?'Gel-Al':'Paket Servis');document.getElementById('orderDialog').classList.remove('payment-view');orderTypeFields();renderOrderMenu();renderOrderCart();renderSavedTableItems();renderOrderSummary();document.getElementById('orderDialog').showModal()}catch(error){toast(error.message||'Adisyon açılamadı.',true)}}
function render(){if(!me)return;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.getElementById('pageTitle').textContent=({orders:'Paket siparişleri',courier:'Kurye çalışma ekranı',pickup:'Gel Al siparişleri',tables:'Masa siparişleri',reports:'Geçmiş kasa raporları',packageHistory:'Paket geçmişi',team:'Ekip ve erişim',menu:'Tanımlamalar',history:'İşlem geçmişi',settings:'Platform bağlantıları',costs:'Reçete & Tüketim',printers:'Yazıcılar'})[view];const app=document.getElementById('app');if(view==='orders'){let a=eligible();app.innerHTML=`<div class="heading"><div><h2>Paket siparişleri.</h2><div class="sub">Easy Wingy & Easy Macaroni · Paket hazırlama ve kurye akışı</div></div><button class="primary" data-action="newOrder" data-service="package">+ Yeni paket siparişi</button></div><div class="stats">${stat('Aktif sipariş',a.filter(o=>o.stage<4).length,'Bugünün açık paketleri')}${stat('Kurye bekleyen',a.filter(o=>o.stage===2).length,'Hazır ve yola çıkmamış paketler')}${stat('Yoldaki paket',a.filter(o=>o.stage===3).length,'Teslimata çıkan siparişler')}${stat('Tamamlanan satış',money(sum(a.filter(o=>o.stage===4))),'Teslim edilen siparişler')}</div>${!orders.length?'<div class="section"><h3>Ortak veritabanı hazır.</h3><p class="fine">Yeni paket siparişini sağ üstten oluştur. Hazırlık ve kurye adımları bu ekranda takip edilir.</p></div>':''}<div class="toolbar"><input id="search" aria-label="Sipariş ara" placeholder="Sipariş no, müşteri veya ürün ara…" value="${esc(query)}"><select id="brandFilter" aria-label="Marka filtresi"><option value="all">Tüm markalar</option><option value="wingy">Easy Wingy</option><option value="mac">Easy Macaroni</option><option value="mixed">Easy Group</option></select><select id="platformFilter" aria-label="Platform filtresi"><option value="all">Tüm platformlar</option><option>Yemeksepeti</option><option>Trendyol</option><option>Restoran</option><option>Telefon</option><option>WhatsApp</option></select></div><div id="board" class="board">${board(a)}</div>`;document.getElementById('brandFilter').value=brandFilter;document.getElementById('platformFilter').value=platformFilter;document.getElementById('search').oninput=e=>{query=e.target.value;document.getElementById('board').innerHTML=board(eligible())};document.getElementById('brandFilter').onchange=e=>{brandFilter=e.target.value;render()};document.getElementById('platformFilter').onchange=e=>{platformFilter=e.target.value;render()}}else if(view==='courier'){const mine=orders.filter(o=>o.serviceType==='package'&&o.courierId===activeCourier);let shown=courierTab==='pool'?orders.filter(o=>o.serviceType==='package'&&o.stage===2&&!o.courierId):mine.filter(o=>o.stage<4);app.innerHTML=`<div class="heading"><div><h2>${activeCourier?'Merhaba, '+esc(person(activeCourier))+'.':'Kurye ekibini oluştur.'}</h2><div class="sub">Hazır paketleri al, teslimatlarını yönet.</div></div></div>${isAdmin()?`<div class="courier-head"><label>Yönetici kurye önizlemesi: <select class="courier-choice" id="courierChoice" aria-label="Kurye önizlemesi">${couriers().map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')||'<option value="">Henüz kurye yok</option>'}</select></label><span class="fine">İşlemler yönetici adına kaydedilir. Kuryeler kendi hesaplarında yalnızca kendi paketlerini görür.</span></div>`:''}<div class="stats">${stat('Üzerimdeki paket',mine.filter(o=>o.stage<4).length,'Ayrılan ve yoldaki paketler')}${stat('Teslim ettiğim',mine.filter(o=>o.stage===4).length,'Bugünün tamamlananları')}${stat('Nakit tahsilatım',money(sum(mine.filter(o=>o.stage===4&&o.payment==='Nakit'))),'Teslimatı tamamlanan paketler')}${stat('Kart tahsilatım',money(sum(mine.filter(o=>o.stage===4&&o.payment==='Kapıda kart'))),'Online ödemeler dahil değil')}</div><div class="tabbuttons"><button class="${courierTab==='mine'?'selected':''}" data-action="mine">Paketlerim</button><button class="${courierTab==='pool'?'selected':''}" data-action="pool">Hazır paket havuzu (${orders.filter(o=>o.serviceType==='package'&&o.stage===2&&!o.courierId).length})</button></div><div class="courier-grid" style="margin-top:20px">${shown.map(o=>card(o,'courier')).join('')||'<div class="section fine">Burada henüz paket yok. Hazır paket havuzunu kontrol edebilirsin.</div>'}</div>`;if(isAdmin()){document.getElementById('courierChoice').value=activeCourier;document.getElementById('courierChoice').onchange=e=>{activeCourier=e.target.value;render()}}}else if(view==='pickup'){renderPickup()}else if(view==='tables'){renderTables()}else if(view==='reports'){renderReports()}else if(view==='packageHistory'){renderPackageHistory()}else if(view==='menu'){renderMenu()}else if(view==='team'){renderTeam()}else if(view==='costs'){window.dispatchEvent(new CustomEvent('easypos-cost-view'))}else if(view==='printers'){renderPrinters()}else if(view==='history'){app.innerHTML=`<div class="heading"><div><h2>Her işlemin izi var.</h2><div class="sub">Son 60 durum değişikliği · sunucu kaydı</div></div><button data-action="historyRefresh">Yenile</button></div><div class="section"><div class="tablewrap"><table><thead><tr><th>Saat</th><th>Sipariş</th><th>İşlem</th><th>Yapan</th></tr></thead><tbody>${events.map(e=>`<tr><td>${new Intl.DateTimeFormat('tr-TR',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Istanbul'}).format(new Date(e.created))}</td><td>#${e.order_id}</td><td>${esc(e.detail)}</td><td>${esc(e.actor_name||'Çalışan')}</td></tr>`).join('')||'<tr><td colspan="4">Henüz işlem kaydı yok.</td></tr>'}</tbody></table></div></div>`}else{app.innerHTML=`<div class="heading"><div><h2>Canlı bağlantılara hazırlık.</h2><div class="sub">Ortak veri hazır. Sırada platform entegrasyonları var.</div></div></div><div class="section"><h3>Sipariş kanalları</h3>${['Easy Wingy · Yemeksepeti','Easy Wingy · Trendyol','Easy Macaroni · Yemeksepeti','Easy Macaroni · Trendyol'].map(s=>`<div class="integration"><strong>${s}</strong><span class="badge">Bağlı değil</span></div>`).join('')}<p class="fine">Bu sürüm platformlardan sipariş almaz ve durum göndermez. API anahtarları tarayıcıya girilmez; canlı bağlantılar sunucu tarafında kurulacak.</p></div><div class="section"><h3>Bu sürümde çalışanlar</h3><p class="fine">Ortak sunucu veritabanı · Yönetici hesabı ve kullanıcı adı/PIN ile kurye yetkileri · 5 saniyede bir senkronizasyon · Sunucuda tek kurye ataması · Çakışan işlemlerde uyarı · İşlem geçmişi · Tahsilat özeti.</p><h3>Erişim durumu</h3><p class="fine">Site artık bağlantıya sahip herkesçe açılabilir. Kuryeler kullanıcı adı ve PIN ile giriş yapar; yönetici sipariş alanı ayrıca yönetici hesabıyla korunur.</p></div>`}}
function renderTeam(){document.getElementById('app').innerHTML=`<div class="heading"><div><h2>Doğru paket, doğru kişi.</h2><div class="sub">Kullanıcı adı ve PIN ile kurye hesapları.</div></div></div><div class="section"><h3>ChatGPT'den bağımsız yönetici girişi</h3><p class="fine">Mevcut yönetici oturumunla bir kez kullanıcı adı ve PIN belirle. Bundan sonra bu bilgilerle doğrudan giriş yapabilirsin.</p><form id="adminLoginForm"><div class="form-grid"><label>Yönetici kullanıcı adı<input name="username" pattern="[a-z0-9_]{3,30}" maxlength="30" required value="${esc(team.find(p=>p.id==='owner')?.username||'melih')}"></label><label>Yönetici PIN<input name="pin" type="password" inputmode="numeric" pattern="[0-9]{6,12}" minlength="6" maxlength="12" required autocomplete="new-password" placeholder="6–12 rakam"></label></div><div class="form-actions"><button class="primary">Yönetici girişini kaydet</button></div></form></div><div class="section"><h3>Kurye ekle</h3><p class="fine">Beş kurye kaydı hazır. PIN'leri sen belirleyeceksin. PIN kaydedilmeden kurye girişi yapılamaz.</p><form id="teamForm"><div class="form-grid"><label>Ad soyad<input name="name" maxlength="70" required placeholder="Kurye adı"></label><label>Kullanıcı adı<input name="username" pattern="[a-z0-9_]{3,30}" maxlength="30" required placeholder="kullanici_adi"></label></div><div class="form-actions"><button class="primary" type="submit">Kurye ekle</button></div></form></div><div class="section"><h3>Ekip</h3><div class="tablewrap"><table><thead><tr><th>Ad</th><th>Kullanıcı adı</th><th>Görev</th><th>Giriş durumu</th><th></th></tr></thead><tbody>${team.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.username||'Yönetici hesabı')}</td><td>${p.role==='admin'?'Yönetici':'Kurye'}</td><td>${!p.active?'Pasif':p.username?(p.pin_ready?'PIN hazır':'PIN bekleniyor'):'ChatGPT hesabı'}</td><td>${p.role==='courier'&&p.username?`<button data-action="setPin" data-id="${esc(p.id)}">${p.pin_ready?'PIN değiştir':'PIN belirle'}</button> `:''}${p.id!=='owner'&&p.id!==me.id?`<button data-action="toggle" data-id="${esc(p.id)}" data-active="${p.active?0:1}">${p.active?'Pasife al':'Etkinleştir'}</button>`:'Hesap sahibi'}</td></tr>`).join('')||'<tr><td colspan="5">Yükleniyor…</td></tr>'}</tbody></table></div><p class="fine">Site adresi kuryelerle paylaşılabilir. Kuryeler kullanıcı adı ve PIN ile girer; sipariş ve yönetim verileri oturum ve rol kontrolüyle korunur.</p></div>`;document.getElementById('adminLoginForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(await mutate('team',{action:'set_admin_login',username:f.get('username'),pin:f.get('pin')})){e.target.reset();await loadTeam();toast('Yönetici kullanıcı adı ve PIN kaydedildi.')}};document.getElementById('teamForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(await mutate('team',{action:'create_courier',name:f.get('name'),username:f.get('username')})){await loadTeam();toast('Kurye eklendi. Şimdi PIN belirleyebilirsin.')}}}
function definitionProducts(){return products.filter(p=>(menuCategory==='all'||p.category===menuCategory)&&(!definitionSearch||(p.name+' '+p.category).toLocaleLowerCase('tr').includes(definitionSearch.toLocaleLowerCase('tr'))))}
function definitionCustomerRows(){const q=definitionSearch.toLocaleLowerCase('tr');return customerRows.filter(c=>!q||(c.name+' '+c.phone+' '+c.address).toLocaleLowerCase('tr').includes(q))}
function definitionDialog(kind,data={}){const dlg=document.getElementById('definitionDialog'),body=document.getElementById('definitionDialogBody');document.getElementById('definitionForm').dataset.kind=kind;document.getElementById('definitionDialogTitle').textContent=kind==='product'?(data.id?'Ürünü düzenle':'Yeni ürün ekle'):kind==='category'?(data.id?'Kategoriyi düzenle':'Yeni kategori'):kind==='customer'?(data.id?'Müşteriyi düzenle':'Yeni müşteri'):data.rate!==undefined?'KDV oranını düzenle':'KDV oranı ekle';let html='';if(kind==='product')html=`<input type="hidden" name="id" value="${esc(data.id||'')}"><label>Ürün adı<input name="name" maxlength="100" value="${esc(data.name||'')}" required></label><label>Kategori<select name="category">${menuCategories.map(c=>`<option value="${esc(c.name)}" ${data.category===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Satış fiyatı (TL)<input name="price" type="number" min="0.01" step="0.01" value="${data.ysPrice?Number(data.ysPrice)/100:''}" required></label><label>Marka<select name="brand"><option value="wingy" ${data.brand!=='mac'?'selected':''}>Easy Wingy</option><option value="mac" ${data.brand==='mac'?'selected':''}>Easy Macaroni</option></select></label><label>KDV oranı<select name="vatRate">${vatRates.map(x=>`<option value="${x}" ${Number(data.vatRate??10)===Number(x)?'selected':''}>%${x}</option>`).join('')}</select></label><label class="definition-check"><input name="active" type="checkbox" ${data.active===false?'':'checked'}> Aktif ürün</label>${data.id?'<button type="button" class="danger-action" data-def-delete-product="'+esc(data.id)+'">Ürünü pasife al</button>':''}`;else if(kind==='category')html=`<input type="hidden" name="id" value="${esc(data.id||'')}"><label>Kategori adı<input name="name" maxlength="60" value="${esc(data.name||'')}" required></label>`;else if(kind==='customer')html=`<input type="hidden" name="id" value="${esc(data.id||'')}"><label>Ad Soyad<input name="name" maxlength="90" value="${esc(data.name||'')}" required></label><label>Telefon<input name="phone" maxlength="30" type="tel" value="${esc(data.phone||'')}" required></label><label>Açık Adres<textarea name="address" maxlength="240" rows="3">${esc(data.address||'')}</textarea></label><label>Bakiye (TL)<input name="balance" type="number" step="0.01" value="${Number(data.balance)||0}"></label>${data.id?'<button type="button" class="danger-action" data-def-delete-customer="'+esc(data.id)+'">Müşteriyi sil</button>':''}`;else html=`${data.rate!==undefined?`<input type="hidden" name="oldRate" value="${Number(data.rate)}">`:''}<label>KDV oranı (%)<input name="rate" type="number" min="0" max="100" step="1" value="${data.rate??''}" required></label>${data.rate!==undefined?'<button type="button" class="danger-action" data-def-delete-vat="'+Number(data.rate)+'">KDV oranını sil</button>':''}`;body.innerHTML=html;dlg.showModal()}
function renderMenu(){const app=document.getElementById('app'),tabs=[['products','Menü ve Ürünler'],['customers','Müşteriler'],['vat','KDV Oranları']];let content='';if(definitionTab==='products'){const rows=definitionProducts();content=`<div class="definition-layout"><aside class="definition-categories"><div class="definition-category-head"><h3>Kategoriler</h3><button data-def-action="add-category">+</button></div><button class="category-pick ${menuCategory==='all'?'selected':''}" data-def-category="all">Tüm kategoriler</button>${menuCategories.map(c=>`<div class="category-row"><button class="category-pick ${menuCategory===c.name?'selected':''}" data-def-category="${esc(c.name)}">${esc(c.name)}</button><button class="icon-action" title="Düzenle" data-def-edit-category="${esc(c.id)}">✎</button><button class="icon-action" title="Sil" data-def-delete-category="${esc(c.id)}">×</button></div>`).join('')}</aside><section class="definition-products"><div class="definition-toolbar"><input id="definitionSearch" placeholder="Ürün veya kategori ara…" value="${esc(definitionSearch)}"><button class="primary" data-def-action="add-product">+ Yeni Ürün Ekle</button></div><div class="definition-product-grid">${rows.map(p=>`<button class="definition-product-card" data-def-edit-product="${esc(p.id)}"><span class="definition-product-title">${esc(p.name)}</span><small>${esc(p.category)} · ${p.brand==='mac'?'Easy Macaroni':'Easy Wingy'} · KDV %${Number(p.vatRate)||0}</small><strong>${money((Number(p.ysPrice)||0)/100)}</strong><em class="badge ${p.active?'live':''}">${p.active?'Aktif':'Pasif'}</em></button>`).join('')||'<div class="section fine">Bu kategoride ürün yok.</div>'}</div></section></div>`}else if(definitionTab==='customers'){const rows=definitionCustomerRows();content=`<section class="section"><div class="definition-toolbar"><input id="definitionSearch" placeholder="Müşteri, telefon veya adres ara…" value="${esc(definitionSearch)}"><button class="primary" data-def-action="add-customer">+ Yeni Müşteri</button></div>${reportTable(['Ad Soyad','Telefon','Açık Adres','Bakiye',''],rows.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.phone)}</td><td>${esc(c.address)}</td><td>${money(Number(c.balance)||0)}</td><td><button data-def-edit-customer="${esc(c.id)}">Düzenle</button></td></tr>`).join(''),'Kayıtlı müşteri yok.')}</section>`}else{content=`<section class="section"><div class="definition-toolbar"><div><h3>KDV oranları</h3><p class="fine">Ürün kartlarında kullanılabilen oranlar</p></div><button class="primary" data-def-action="add-vat">+ KDV Oranı</button></div>${reportTable(['Oran','Kullanım',''],vatRates.map(rate=>`<tr><td>%${rate}</td><td>${products.filter(p=>Number(p.vatRate)===Number(rate)&&p.active).length} aktif ürün</td><td><button data-def-edit-vat="${rate}">Düzenle</button><button data-def-delete-vat="${rate}">Sil</button></td></tr>`).join(''))}</section>`}app.innerHTML=`<div class="heading"><div><h2>Tanımlamalar.</h2><div class="sub">Menü, müşteri ve KDV bilgileri Cloudflare D1 üzerinde yönetilir.</div></div></div><div class="tabs definition-tabs">${tabs.map(([key,label])=>`<button class="${definitionTab===key?'selected':''}" data-definition-tab="${key}">${label}</button>`).join('')}</div>${content}<dialog id="definitionDialog" class="definition-dialog"><form id="definitionForm"><div class="definition-dialog-head"><h3 id="definitionDialogTitle"></h3><button type="button" class="icon-action" data-def-close>×</button></div><div id="definitionDialogBody" class="definition-dialog-body"></div><div class="dialog-actions"><button type="button" data-def-close>Vazgeç</button><button type="submit" class="primary">Kaydet</button></div></form></dialog>`;const search=document.getElementById('definitionSearch');if(search)search.oninput=e=>{definitionSearch=e.target.value;const focus=e.target.selectionStart;renderMenu();const next=document.getElementById('definitionSearch');next?.focus();next?.setSelectionRange(focus,focus)};document.getElementById('definitionForm').onsubmit=async e=>{e.preventDefault();const form=e.target,fd=new FormData(form),kind=form.dataset.kind;let ok;if(kind==='product'){const price=Math.round(Number(String(fd.get('price')||'').replace(',','.'))*100);ok=await mutate('menu/manage',{action:'product_save',id:fd.get('id')||undefined,name:fd.get('name'),category:fd.get('category'),ysPrice:price,brand:fd.get('brand'),vatRate:Number(fd.get('vatRate')),active:fd.has('active')})}else if(kind==='category')ok=await mutate('menu/manage',{action:'category_save',id:fd.get('id')||undefined,name:fd.get('name')});else if(kind==='customer')ok=await mutate('customers/manage',{action:'save',id:fd.get('id')||undefined,name:fd.get('name'),phone:fd.get('phone'),address:fd.get('address'),balance:fd.get('balance')});else ok=await mutate('menu/manage',{action:fd.get('oldRate')!==null?'vat_update':'vat_save',oldRate:fd.get('oldRate')!==null?Number(fd.get('oldRate')):undefined,rate:Number(fd.get('rate'))});if(ok){document.getElementById('definitionDialog')?.close();await loadMenu()}}}
async function loadMenu(){try{const data=await api('menu'),customerData=await api('customers');products=data.products||[];menuCategories=data.categories||[];vatRates=data.vatRates||[];customerRows=customerData.customers||[];products.forEach(p=>p._originalPrice=p.ysPrice);if(view==='menu')renderMenu()}catch(e){toast(e.message,true)}}
async function loadOrderHistory(target){if(target==='reports'&&!products.length){try{products=(await api('menu')).products}catch{}}const from=target==='reports'?(reportFrom||lastDay):(packageFrom||lastDay),to=target==='reports'?(reportTo||lastDay):(packageTo||lastDay);try{const p=new URLSearchParams({from,to});if(target==='packageHistory'){p.set('brand',historyBrand);p.set('platform',historyPlatform);if(historyCourier!=='all')p.set('courier',historyCourier)}const data=await api('history?'+p.toString());if(target==='reports'){reportOrders=data.orders;reportFrom=data.from;reportTo=data.to;if(view==='reports')renderReports()}else{packageOrders=data.orders;packageFrom=data.from;packageTo=data.to;if(view==='packageHistory')renderPackageHistory();if(data.truncated)toast('Kayıt listesi ilk 5.000 siparişle sınırlandı.',true)}}catch(e){toast(e.message,true)}}
function filteredPackageOrders(){const q=packageSearch.toLocaleLowerCase('tr');return packageOrders.filter(o=>!q||[o.id,o.customer,o.area,...o.items].join(' ').toLocaleLowerCase('tr').includes(q))}
function orderTable(a){return `<div class="tablewrap"><table><thead><tr><th>Teslim</th><th>#</th><th>Müşteri / adres</th><th>Marka</th><th>Platform</th><th>Kurye</th><th>Ürünler</th><th>İndirim</th><th>İade / Zayi</th><th>Net tutar</th><th>Ödeme detayları</th></tr></thead><tbody>${a.map(o=>`<tr><td>${new Intl.DateTimeFormat('tr-TR',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Istanbul'}).format(new Date(o.delivered))}</td><td>${o.id}</td><td>${esc(o.customer)}<br><small>${esc(o.area)}</small></td><td>${brand(o.brand)}</td><td>${esc(o.platform)}</td><td>${esc(o.courierId?person(o.courierId):'—')}</td><td>${o.items.map((item,index)=>orderLineMarkup(o,item,index)).join('<br>')}</td><td>${o.discountAmount?`−${money(o.discountAmount)}`:'—'}</td><td>${o.refundTotal?money(o.refundTotal):'—'}</td><td>${money(o.reportTotal??o.total)}</td><td>${(o.payments||[]).map(p=>`${esc(p.method)} ${p.amount<0?'−':''}${money(Math.abs(p.amount))}${p.status==='receivable'?' · cari':''}`).join('<br>')||esc(o.payment)}</td></tr>`).join('')||'<tr><td colspan="11">Bu aralıkta tamamlanan sipariş yok.</td></tr>'}</tbody></table></div>`}
function printerConfig(){try{const value=JSON.parse(localStorage.getItem('easypos-printers')||'[]');if(Array.isArray(value))return value;return [{id:'legacy-cashier',name:value.cashier||'',types:value.cashier?['Adisyon']:[]},{id:'legacy-kitchen',name:value.kitchen||'',types:value.kitchen?['Mutfak']:[]}].filter(x=>x.name)}catch{return []}}
let printerDevices=[],printerDiscovery=[],printerServiceState={bridgeReady:false,webhooks:[]};
async function renderPrinters(){const opts=printOptions(),types=['Adisyon','Mutfak','Kurye'];try{const data=await api('printers');printerDevices=(data.printers||[]).map(p=>({...p,types:Array.isArray(p.types)?p.types:JSON.parse(p.types||'[]')}));printerDiscovery=data.discovered||[];printerServiceState={bridgeReady:data.bridgeReady,webhooks:data.webhooks||[],printQueue:data.printQueue||[]};if(!data.offline&&!localStorage.getItem('easypos-printer-d1-migrated')){const legacy=printerConfig();for(const item of legacy)await api('printers/manage',{action:'save',id:item.id,name:item.name,address:item.address||'',types:item.types||[],mainChannel:item.types?.[0]||'Adisyon'});localStorage.setItem('easypos-printer-d1-migrated','1');if(legacy.length){const fresh=await api('printers');data.printers=fresh.printers;data.discovered=fresh.discovered;printerServiceState={bridgeReady:fresh.bridgeReady,webhooks:fresh.webhooks||[],printQueue:fresh.printQueue||[]};printerDevices=(fresh.printers||[]).map(p=>({...p,types:Array.isArray(p.types)?p.types:JSON.parse(p.types||'[]')}));printerDiscovery=fresh.discovered||[]}}}catch{printerDevices=printerDevices||[];printerDiscovery=printerDiscovery||[]}const printers=printerDevices,queueFailed=Number(printerServiceState.printQueue?.find(x=>x.status==='failed')?.count)||0,model=localStorage.getItem('easypos-printer-model')||'multiple',sample={id:234,created:Date.now(),serviceType:'package',brand:'mixed',customer:'Örnek Müşteri',phone:'05xx xxx xx xx',area:'Yelki Mah. Örnek Sokak No: 10',platform:'Restoran',payment:'Nakit',note:'Kapıda arayın',subtotal:680,discountAmount:20,total:660,items:['2 × Easy Crispy Bites 6’lı · ₺312,00','1 × Penne Pesto Parmesan · ₺68,00'],adjustments:[{index:0,status:'product_note',note:'Sosu ayrı'}]};const toggles=[['compact','Boşluklar daraltılsın'],['orderNo','Sipariş numarası gösterilsin'],['merge','Aynı ürünler birleştirilsin'],['notes','Notlar gösterilsin'],['vat','KDV bilgisi gösterilsin']];document.getElementById('app').innerHTML=`<div class="heading"><div><h2>Yazıcılar ve fişler.</h2><div class="sub">Yerel köprü fiş kuyruğunu izler ve seçilen bilgisayar yazıcısına iletir.</div></div></div><div class="tabs">${[['printers','Yazıcılar'],['design','Çıktı Tasarımı']].map(([key,label])=>`<button class="${printerTab===key?'selected':''}" data-printer-tab="${key}">${label}</button>`).join('')}</div>${printerTab==='printers'?`<div class="printer-two-column"><section class="section"><div class="printer-table-head"><div><h3>Tanımlı yazıcılar</h3><p class="fine">Köprü son 2 dakika içinde yazıcı gördüyse durum çevrimiçi görünür.</p></div><button class="primary" data-printer-add>+ Yeni Yazıcı Ekle</button></div><div class="tablewrap"><table><thead><tr><th>Yazıcı Adı</th><th>Yazıcı Türü</th><th>Durum</th><th>İşlemler</th></tr></thead><tbody>${printers.map(p=>{let seen=Number(p.last_seen)>Date.now()-120000;return `<tr><td><strong>${esc(p.name)}</strong><br><small>${esc(p.address||'Yerel yazıcı')}</small></td><td>${(p.types||[]).map(t=>`<span class="badge printer-type-badge">#${esc(t)}</span>`).join(' ')||'—'}</td><td><span class="badge ${seen?'live':''}">${seen?'Online':'Tanımlı'}</span></td><td><div class="printer-actions"><button data-printer-edit="${esc(p.id)}">Düzenle</button><button data-printer-test="${esc(p.id)}">Test Yazdır</button><button data-printer-delete="${esc(p.id)}">Sil</button></div></td></tr>`}).join('')||'<tr><td colspan="4">Henüz yazıcı tanımlanmadı.</td></tr>'}</tbody></table></div><div class="printer-footer-add"><button class="primary" data-printer-add>＋ Yeni Yazıcı Ekle</button></div><dialog id="printerDialog" class="printer-dialog"><form id="printerForm"><input type="hidden" id="printerId"><h3 id="printerDialogTitle">Yeni yazıcı ekle</h3><label class="printer-name-field">Köprünün bulduğu yazıcı<select id="printerDiscovered" class="bridge-select"><option value="">Yazıcı seçin veya aşağıya elle yazın</option>${printerDiscovery.map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('')}</select></label><label class="printer-name-field">Yazıcı adı / bilgisayardaki kuyruk adı<input id="printerName" maxlength="120" required placeholder="Örn. MUTFAK, KASA, Epson_TMT20"></label><label class="printer-name-field">Yerel ağ adresi (isteğe bağlı)<input id="printerAddress" maxlength="160" placeholder="USB için boş bırakın · Ethernet: 192.168.1.50"></label><div class="printer-type-options"><span>Bu yazıcı hangi fişleri bassın?</span>${types.map(t=>`<label class="switch-row"><span>#${t}</span><input type="checkbox" data-printer-type="${t}"></label>`).join('')}</div><label class="printer-name-field">Ana kanal<select id="printerMainChannel" class="bridge-select">${types.map(t=>`<option value="${t}">${t}</option>`).join('')}</select></label><p class="fine">Bir cihaz birden fazla fiş türünü basabilir. Ad, köprüde bulunan yazıcı kuyruğuyla aynı olmalı.</p><div class="dialog-actions"><button type="button" data-printer-cancel>Vazgeç</button><button type="submit" class="primary">Yazıcıyı kaydet</button></div></form></dialog></section><aside><section class="printer-side-card"><h3>Yazıcı modeli</h3><div class="printer-models"><label><input type="radio" name="printerModel" data-printer-model="multiple" ${model==='multiple'?'checked':''}><span><b>Birden fazla yazıcı</b><br><small>USB veya Ethernet · Adisyon, mutfak ve kurye fişleri ayrı yazıcıya yönlenebilir.</small></span></label><label><input type="radio" name="printerModel" data-printer-model="single" ${model==='single'?'checked':''}><span><b>Tek yazıcı</b><br><small>Kasa ve mutfak fişleri tek yerel yazıcı kuyruğunda basılır.</small></span></label></div></section><section class="printer-side-card"><h3>Yerel Yazıcı Köprüsü</h3><p class="fine">Bu bilgisayarda Node.js ve macOS/Linux CUPS yazıcı araçlarıyla çalışır. Yazdırma onay penceresi açmadan fiş kuyruğunu yazdırır.</p><a class="button-link" href="/print-bridge.js" download="print-bridge.js">print-bridge.js indir</a><p class="fine">İndirilen dosyayı bilgisayarda çalıştırmak ve yazıcıları keşfetmek için bir erişim anahtarı oluştur.</p><button class="primary" data-bridge-key>${printerServiceState.bridgeReady?'Köprü anahtarını yenile':'Yerel köprü anahtarı oluştur'}</button><div id="bridgeKeyOutput"></div><p class="fine">Köprünün çalışacağı cihazda: <code>node print-bridge.js</code> komutundan önce EASYPOS_URL ve EASYPOS_BRIDGE_TOKEN ortam değişkenlerini tanımla.</p></section><section class="printer-side-card"><h3>Fiş kuyruğu</h3><p class="fine">Yazdırma kuyruğu durumu D1 üzerinden izlenir.</p><p class="fine">Bekleyen: ${Number(printerServiceState.printQueue?.find(x=>x.status==='pending')?.count)||0} · Yazdırılıyor: ${Number(printerServiceState.printQueue?.find(x=>x.status==='processing')?.count)||0} · Hatalı: ${queueFailed}</p>${queueFailed?'<button data-printer-retry>Hatalı fişleri yeniden dene</button>':''}</section><section class="printer-side-card"><h3>Online sipariş uçları</h3><p class="fine">Onaylanmış siparişleri doğrudan Hazırlanıyor aşamasına alan webhook uçları:</p><code class="integration-key">POST /api/webhooks/yemeksepeti<br>POST /api/webhooks/trendyol</code><div class="printer-actions" style="margin-top:12px"><button data-webhook="Yemeksepeti">Yemeksepeti anahtarı</button><button data-webhook="Trendyol">Trendyol anahtarı</button></div><div id="webhookKeyOutput"></div><p class="fine">Oluşturulan anahtarı sağlayıcının webhook ayarına güvenli biçimde ekle. Sağlayıcı hesabında webhook açma ve payload eşlemesi ayrıca gerekir.</p></section></aside></div>`:`<div class="printer-design"><section class="section"><h3>Fiş ayarları</h3>${toggles.map(([key,label])=>`<label class="switch-row"><span>${label}</span><input type="checkbox" data-print-option="${key}" ${opts[key]?'checked':''}></label>`).join('')}<label class="switch-row">Yazı boyutu <select id="printFontSize"><option ${opts.fontSize===11?'selected':''}>11</option><option ${opts.fontSize===12?'selected':''}>12</option><option ${opts.fontSize===13?'selected':''}>13</option><option ${opts.fontSize===14?'selected':''}>14</option><option ${opts.fontSize===15?'selected':''}>15</option></select></label><p class="fine">Ayarlar bu bilgisayarda saklanır. Mutfak fişinde fiyat ve müşteri adresi yer almaz.</p></section><section class="section"><h3>Canlı adisyon önizlemesi · 80mm</h3><div class="receipt-preview">${printBrandLogos(sample)}<div class="preview-meta">Müşteri: ${esc(sample.customer)}<br>Ödeme tipi: ${sample.payment}<br>Adres: ${esc(sample.area)}<br>Kanal: ${sample.platform}<br><b>Sipariş notu: ${sample.note}</b></div>${receiptItemsTable(sample,false)}${opts.vat?'<div class="preview-meta">KDV (dahil %10): '+receiptMoney(sample.total*10/110)+'</div>':''}<div class="receipt-grand-total"><span>Toplam</span><b>${receiptMoney(sample.total)}</b></div></div><h3>Mutfak önizlemesi</h3><div class="receipt-preview">${printBrandLogos(sample)}<b class="preview-brand">MUTFAK · PAKET SERVİS</b>${receiptItemsTable(sample,true)}<b>Sipariş notu: ${esc(sample.note)}</b></div></section></div>`}`;window.printerDevices=printerDevices;document.querySelectorAll('[data-print-option]').forEach(input=>input.onchange=()=>{const next=printOptions();next[input.dataset.printOption]=input.checked;localStorage.setItem('easypos-print-options',JSON.stringify(next));renderPrinters()});document.querySelectorAll('[data-printer-model]').forEach(input=>input.onchange=()=>localStorage.setItem('easypos-printer-model',input.dataset.printerModel));const fs=document.getElementById('printFontSize');if(fs)fs.onchange=()=>{const next=printOptions();next.fontSize=Number(fs.value);localStorage.setItem('easypos-print-options',JSON.stringify(next));renderPrinters()};const form=document.getElementById('printerForm');if(form){document.getElementById('printerDiscovered').onchange=e=>{if(e.target.value)document.getElementById('printerName').value=e.target.value};form.onsubmit=async e=>{e.preventDefault();const id=document.getElementById('printerId').value||undefined,name=document.getElementById('printerName').value.trim(),address=document.getElementById('printerAddress').value.trim(),selected=[...document.querySelectorAll('[data-printer-type]:checked')].map(x=>x.dataset.printerType),mainChannel=document.getElementById('printerMainChannel').value;if(!name||!selected.length){toast('Yazıcı adı ve en az bir tür seç.',true);return}try{await api('printers/manage',{action:'save',id,name,address,types:selected,mainChannel});document.getElementById('printerDialog').close();toast('Yazıcı D1’e kaydedildi.');await renderPrinters()}catch(error){toast(error.message,true)}};document.getElementById('printerDialog').onclick=e=>{if(e.target.closest('[data-printer-cancel]'))document.getElementById('printerDialog').close()}}}

function reportRows(){return reportOrders.filter(o=>o.stage===4)}
function reportCurrency(value){return money((Number(value)||0)/100)}
function reportExportRows(){const rows=reportRows();if(reportTab==='products'){const out=new Map();for(const o of rows)for(const item of o.items||[]){const line=parseLine(item);if(!line)continue;const p=products.find(x=>x.name===line.name),key=line.name,rec=out.get(key)||{name:key,category:p?.category||'Diğer',qty:0,revenue:0};rec.qty+=line.quantity;rec.revenue+=line.quantity*line.unit;out.set(key,rec)}return [['Kategori','Ürün','Adet','Ciro'],...[...out.values()].map(x=>[x.category,x.name,x.qty,(x.revenue/100).toFixed(2)])]}if(reportTab==='audit'){return [['Sipariş','Tarih','İşlem','Ürün','Tutar','Personel'],...rows.flatMap(o=>(o.adjustments||[]).filter(x=>['cancelled','refunded','comp','waste'].includes(x.status)).map(x=>[o.id,new Date(x.created||o.delivered).toLocaleString('tr-TR'),x.status,o.items?.[x.index]||'',((x.amount||0)/100).toFixed(2),person(x.actor)]))]}return [['Adisyon','Kapanış zamanı','Kanal / Masa','Müşteri','İndirim','Toplam','Ödeme'],...rows.map(o=>[o.id,new Date(o.delivered||o.created).toLocaleString('tr-TR'),o.serviceType==='table'?'Masa '+o.tableNo:o.serviceType==='pickup'?'Gel-Al':'Paket',o.customer,o.discountAmount||0,(o.reportTotal??o.total).toFixed(2),o.payment])]}function reportTable(headers,body,empty='Kayıt yok.'){return `<div class="tablewrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}">${empty}</td></tr>`}</tbody></table></div>`}
function renderReports(){const all=reportRows(),paymentNames=['Nakit','Kapıda kart','Kredi Kartı','YS Online','Trendyol Online','Online','Online Ödeme','Sodexo/Multinet','Açık Hesap (Cari)'],channels=['Masa','Gel-Al','Paket'],methodLabel=(method,platform)=>{const m=String(method||'').trim().toLocaleLowerCase('tr-TR');if(m.includes('yemeksepeti')||m==='ys online')return 'YS Online';if(m.includes('trendyol'))return 'Trendyol Online';if(m==='online'||m==='online ödeme')return platform==='Trendyol'?'Trendyol Online':platform==='Yemeksepeti'?'YS Online':'Online';if(m==='kapıda kart'||m==='kredi kartı'||m==='kart')return 'Kapıda kart';if(m==='açık hesap'||m==='açık hesap (cari)')return 'Açık Hesap (Cari)';return method||'Diğer'},paymentRecords=all.flatMap(o=>{const saved=(Array.isArray(o.payments)?o.payments:[]).filter(p=>['paid','receivable'].includes(p.status));if(saved.length)return saved.map(p=>({order:o,method:methodLabel(p.method,o.platform),amount:safeMoneyValue(p.amount)}));const fallback=methodLabel(o.payment,o.platform);return [{order:o,method:fallback,amount:safeMoneyValue(o.total)}]}),paid=paymentRecords,total=sum(all.map(o=>safeMoneyValue(o.reportTotal??o.total))),received=sum(paid.map(p=>p.amount)),comp=sum(all.flatMap(o=>Array.isArray(o.adjustments)?o.adjustments:[]).filter(x=>x.status==='comp').map(x=>safeMoneyValue(x.amount)))/100,refund=sum(all.map(o=>safeMoneyValue(o.refundTotal)));const bar=(label,value,max,color='#e87848')=>`<div class="report-bar-row"><span>${esc(label)}</span><div><i style="width:${max&&value>0?Math.max(2,Math.min(100,value/max*100)):0}%;background:${color}"></i></div><b>${money(value)}</b></div>`;let content='';if(reportTab==='summary'){const payments=paymentNames.map(method=>({method,amount:sum(paid.filter(p=>p.method===method).map(p=>p.amount)),count:new Set(paid.filter(p=>p.method===method).map(p=>p.order.id)).size})).filter(x=>x.amount>0),channelRows=channels.map(label=>{const list=all.filter(o=>label==='Masa'?o.serviceType==='table':label==='Gel-Al'?o.serviceType==='pickup':o.serviceType==='package');return {label,amount:sum(list.map(o=>safeMoneyValue(o.reportTotal??o.total)))}}),maxPay=Math.max(0,...payments.map(x=>x.amount)),maxChannel=Math.max(0,...channelRows.map(x=>x.amount));content=`<div class="stats">${stat('Net ciro',money(total),`${all.length} kapanmış adisyon`)}${stat('Alınan ödemeler',money(received),'Ödeme kayıtlarından')}${stat('İkram',money(comp),'Ödenmez olarak kaydedilen')}${stat('İade / Zayi',money(refund),'Kayıtlı iade tutarı')}</div><div class="report-grid"><section class="section"><h3>Ödeme tipleri</h3>${payments.map(x=>bar(x.method,x.amount,maxPay)).join('')||'<div class="empty">Ödeme kaydı yok.</div>'}</section><section class="section"><h3>Sipariş kanalları</h3>${channelRows.map(x=>bar(x.label,x.amount,maxChannel,'#56786a')).join('')||'<div class="empty">Kanal verisi yok.</div>'}</section></div><section class="section"><h3>Ödeme dökümü</h3>${reportTable(['Ödeme tipi','Adisyon','Tutar'],payments.map(x=>`<tr><td>${esc(x.method)}</td><td>${x.count}</td><td>${money(x.amount)}</td></tr>`).join(''))}</section>`}
else if(reportTab==='bills'){content=`<section class="section"><h3>Tüm adisyonlar</h3>${reportTable(['Adisyon No','Açılış / Kapanış','Kanal / Masa','İndirim','Toplam'],all.map(o=>`<tr class="report-order-row" data-report-order="${o.id}"><td>#${o.id}</td><td>${new Intl.DateTimeFormat('tr-TR',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Istanbul'}).format(new Date(o.created))}<br><small>${new Intl.DateTimeFormat('tr-TR',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Istanbul'}).format(new Date(o.delivered||o.created))}</small></td><td>${esc(o.serviceType==='table'?'Masa '+o.tableNo:o.serviceType==='pickup'?'Gel-Al':'Paket Servis')} · ${esc(o.platform||'Restoran')}</td><td>${money(o.discountAmount||0)}</td><td>${money(o.reportTotal??o.total)}</td></tr>`).join(''),'Bu tarih aralığında kapanmış adisyon yok.')}</section>`}
else if(reportTab==='busy'){const bins=Array.from({length:24},(_,hour)=>({hour,count:all.filter(o=>Number(new Intl.DateTimeFormat('en-GB',{hour:'2-digit',hourCycle:'h23',timeZone:'Europe/Istanbul'}).format(new Date(o.created)))===hour).length})),max=Math.max(1,...bins.map(x=>x.count));content=`<section class="section"><h3>Saatlik sipariş yoğunluğu</h3><div class="heatmap">${bins.map(x=>`<div title="${String(x.hour).padStart(2,'0')}:00 · ${x.count} sipariş" style="--heat:${(x.count/max).toFixed(2)}"><b>${String(x.hour).padStart(2,'0')}:00</b><strong>${x.count}</strong></div>`).join('')}</div><p class="fine">Yoğunluk, sipariş açılış saatine göre hesaplanır.</p></section>`}
else if(reportTab==='couriers'){const delivered=all.filter(o=>o.serviceType==='package'&&o.courierId),ids=[...new Set([...couriers().map(c=>c.id),...delivered.map(o=>o.courierId)])],num=value=>{const n=Number(value);return Number.isFinite(n)?n:0},methodKey=value=>String(value||'').trim().toLocaleLowerCase('tr-TR'),collected=(o,kind)=>{const rows=Array.isArray(o.payments)?o.payments:[],eligible=rows.filter(p=>!p.status||['paid','receivable'].includes(p.status)),match=method=>kind==='cash'?methodKey(method)==='nakit':kind==='card'?methodKey(method).includes('kart'):['online','online ödeme','ys online','trendyol online'].some(x=>methodKey(method).includes(x));if(rows.length)return eligible.filter(p=>match(p.method)).reduce((n,p)=>n+num(p.amount),0);return match(o.payment)?num(o.reportTotal??o.total):0},duration=o=>{const start=Number(o.created),end=Number(o.delivered);return Number.isFinite(start)&&start>0&&Number.isFinite(end)&&end>0?Math.max(0,(end-start)/60000):0},cashTotal=delivered.reduce((n,o)=>n+collected(o,'cash'),0),cardTotal=delivered.reduce((n,o)=>n+collected(o,'card'),0),courierRevenue=delivered.reduce((n,o)=>n+num(o.reportTotal??o.total),0),shown=reportCourier==='all'?delivered:delivered.filter(o=>String(o.courierId)===String(reportCourier));content=`<div class="stats">${stat('Toplam paket',delivered.length,'Seçili tarih aralığında')}${stat('Nakit tahsilat',money(cashTotal),'Kuryelerin teslim aldığı')}${stat('Kart tahsilat',money(cardTotal),'Kapıda kart / kredi kartı')}${stat('Genel ciro',money(courierRevenue),'Teslim edilen paketler')}</div><section class="section"><h3>Paket ve kurye performansı</h3><p class="fine">Kurye satırına tıklayarak aşağıdaki sipariş listesini filtreleyebilirsin.</p>${reportTable(['Kurye','Teslimat','Ort. süre','Nakit','Kart','Online'],ids.map(id=>{const d=delivered.filter(o=>String(o.courierId)===String(id)),avg=d.length?Math.round(d.reduce((n,o)=>n+duration(o),0)/d.length):0,cash=d.reduce((n,o)=>n+collected(o,'cash'),0),card=d.reduce((n,o)=>n+collected(o,'card'),0),online=d.reduce((n,o)=>n+collected(o,'online'),0);return `<tr class="courier-report-row ${String(reportCourier)===String(id)?'is-selected':''}" data-courier-filter="${esc(id)}"><td>${esc(person(id))}</td><td>${d.length}</td><td>${avg} dk</td><td>${money(cash)}</td><td>${money(card)}</td><td>${money(online)}</td></tr>`}).join(''),'Kurye teslimatı bulunamadı.')}</section><section class="section"><div class="courier-report-detail-head"><h3>Kurye sipariş detayları ${reportCourier==='all'?'· Tüm Kuryeler':'· '+esc(person(reportCourier))}</h3><button data-courier-filter-reset ${reportCourier==='all'?'disabled':''}>Tüm Kuryeler</button></div>${orderTable(shown)}</section>`}
else if(reportTab==='products'){const sums=new Map();for(const o of all)for(const item of o.items||[]){const line=parseLine(item);if(!line)continue;const p=products.find(x=>x.name===line.name),rec=sums.get(line.name)||{name:line.name,category:p?.category||'Diğer',quantity:0,revenue:0};rec.quantity+=line.quantity;rec.revenue+=line.quantity*line.unit;sums.set(line.name,rec)}content=`<section class="section"><h3>Kategori ve ürün satışları</h3>${reportTable(['Kategori','Ürün','Adet','Ciro'],[...sums.values()].sort((a,b)=>b.revenue-a.revenue).map(x=>`<tr><td>${esc(x.category)}</td><td>${esc(x.name)}</td><td>${x.quantity}</td><td>${money(x.revenue/100)}</td></tr>`).join(''))}</section>`}
else{const audits=all.flatMap(o=>(o.adjustments||[]).filter(x=>['cancelled','refunded','comp','waste'].includes(x.status)).map(x=>({o,x})));content=`<section class="section"><h3>İptal, zayi ve ikram denetimi</h3>${reportTable(['Tarih','Sipariş','İşlem','Ürün','Tutar','Personel'],audits.map(({o,x})=>`<tr><td>${new Intl.DateTimeFormat('tr-TR',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Istanbul'}).format(new Date(x.created||o.delivered))}</td><td>#${o.id}</td><td>${x.status==='comp'?'İkram':x.status==='refunded'?'İade':x.status==='waste'?'Zayi':'İptal'}</td><td>${esc(parseLine(o.items?.[x.index])?.name||o.items?.[x.index]||'—')}</td><td>${money((x.amount||0)/100)}</td><td>${esc(person(x.actor))}</td></tr>`).join(''),'Bu aralıkta denetim kaydı yok.')}</section>`}
document.getElementById('app').innerHTML=`<div class="heading"><div><h2>Kasa raporları.</h2><div class="sub">Kapanmış adisyonlar · seçili tarih aralığı</div></div><button data-action="reportCsv">Excel / CSV indir ↓</button></div><form id="reportFilter" class="toolbar report-toolbar"><label>Başlangıç<input type="date" name="from" value="${esc(reportFrom||lastDay)}" required></label><label>Bitiş<input type="date" name="to" value="${esc(reportTo||lastDay)}" required></label><button class="primary">Filtrele</button></form><div class="tabs report-tabs">${[['summary','Özet'],['bills','Tüm Adisyonlar'],['busy','Yoğunluk Raporu'],['couriers','Paket ve Kurye'],['products','Ürün Satış'],['audit','İptal, Zayi ve İkram']].map(([key,label])=>`<button class="${reportTab===key?'selected':''}" data-report-tab="${key}">${label}</button>`).join('')}</div>${content}`;document.getElementById('reportFilter').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);reportFrom=f.get('from');reportTo=f.get('to');loadOrderHistory('reports')}}
