function openDiscountDialog(lineIndex=null){discountTargetLine=Number.isInteger(lineIndex)?lineIndex:null;const current=discountTargetLine===null?null:(activeTableOrder()?.adjustments||[]).find(a=>a.index===discountTargetLine&&a.status==='item_discount');discountEditType=current?.discountType||(discountTargetLine===null?(discountType==='none'?'percent':discountType):'percent');document.getElementById('discountTitle').textContent=discountTargetLine===null?'Adisyon indirimi':'Ürün bazlı indirim';document.getElementById('discountInput').value=current?(current.discountValue/100).toFixed(2):discountTargetLine===null&&discountType!=='none'?(discountValue/100).toFixed(2):'';document.getElementById('discountInputLabel').firstChild.textContent=discountEditType==='percent'?'İndirim yüzdesi':'İndirim tutarı (TL)';document.querySelectorAll('[data-discount-choice]').forEach(b=>b.classList.toggle('selected',b.dataset.discountChoice===discountEditType));document.getElementById('discountInput').max=discountEditType==='percent'?'100':'';document.getElementById('discountInput').placeholder=discountEditType==='percent'?'Örn. 10':'Örn. 50';document.getElementById('discountDialog').showModal()}
