async function submitPopupPayment(mode='save'){const order=activeTableOrder();if(!order){toast('Açık masa adisyonu bulunamadı.',true);return}const indexes=[...selectedBillItems],shares=[...selectedShares.entries()].filter(([index])=>selectedBillItems.has(index)).map(([index,denominator])=>({index,denominator}));let ok=false;if(indexes.length){const amount=selectedBillAmount(order);if(amount<=0){toast('Seçilen ürünlerin tahsil edilecek tutarı yok.',true);return}ok=await mutate('orders/action',{id:order.id,version:order.version,action:'payment_items',paymentMethod,indexes,shares,printRequested:mode==='print'})}else{const typed=Math.round(Number(String(document.getElementById('paymentAmount')?.value||'').replace(',','.'))*100),amount=mode==='settle'||mode==='print'?paymentTotals(order).remaining:typed;if(!Number.isSafeInteger(amount)||amount<=0){toast('Ödeme için sıfırdan büyük bir tutar gir.',true);return}ok=await mutate('orders/action',{id:order.id,version:order.version,action:'payment_add',paymentMethod,amount,printRequested:mode==='print'})}if(!ok)return;selectedBillItems.clear();selectedShares.clear();const current=activeTableOrder();if(!current){document.getElementById('tablePaymentPane').hidden=true;closeOrderDialog();toast('Ödeme alındı ve adisyon kapatıldı.')}else{renderSavedTableItems();renderOrderCart();renderTablePayment();toast('Tahsilat D1 adisyonuna kaydedildi. Kalan tutar açık adisyonda duruyor.')}if(mode==='settle'&&current){document.getElementById('tablePaymentPane').hidden=true;orderPane='products'}}

